report={'qualification':q,'frozen_damage_diagnostic':{k:v for k,v in d.items() if k not in ['trace','source_hashes']},'batches':status,'limits':{'address_space_bytes':512*1024**2,'cpu_s':45,'wall_s':55,'parent_timeout_s':60,'max_worker_audit_calls_per_batch':12,'blas_threads':1},'physical_laws_and_gates_unchanged':True,'full_cut':False,'independent_release_validated':False,'native_newton_integration':False,'simulator':False,'training':False}
